CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE study_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, host_id TEXT NOT NULL REFERENCES users(id), subject TEXT NOT NULL, topic TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE members (session_id INTEGER NOT NULL REFERENCES study_sessions(id), user_id TEXT NOT NULL REFERENCES users(id), joined_at INTEGER NOT NULL, PRIMARY KEY(session_id,user_id));
CREATE TABLE token_events (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), session_id INTEGER NOT NULL REFERENCES study_sessions(id), kind TEXT NOT NULL, amount INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', actor_id TEXT REFERENCES users(id), created_at INTEGER NOT NULL, UNIQUE(user_id,session_id,kind));
CREATE TABLE thanks (session_id INTEGER NOT NULL REFERENCES study_sessions(id), from_user TEXT NOT NULL REFERENCES users(id), to_user TEXT NOT NULL REFERENCES users(id), note TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, PRIMARY KEY(session_id,from_user));
